  "10-uki" = {
    Source = {
      MatchPattern = [
        "nixos_@v+@l-@d.efi"
        "nixos_@v+@l.efi"
        "nixos_@v.efi"
      ];
      Path = "https://download.example.com/";
      Type = "url-file";
    };
    Target = {
      InstancesMax = 2;
      MatchPattern = ''
        nixos_@v+@l-@d.efi"; \
        nixos_@v+@l.efi \
        nixos_@v.efi
      '';
      Mode = "0444";
      Path = "/EFI/Linux";
      PathRelativeTo = "boot";
      TriesDone = 0;
